/* @autogenerated */
import { combineLatest, map, Observable, of, take } from 'rxjs';
import { DisplayProvider } from '@shared/data/display-provider';

/** Lo que necesita `referenceDisplay` del repositorio referenciado. */
export interface ReferenceSource<T> {
  retrieve(key: string): Observable<T | undefined>;
  displayProvider(): DisplayProvider<T>;
}

type Reference = { $ref: string };

/**
 * Pinta una referencia `{ $ref }` (o una lista de ellas) por la etiqueta del elemento referenciado. Sin elemento o
 * sin etiqueta se muestra el propio `$ref`.
 */
export function referenceDisplay<T>(
  repository: ReferenceSource<T>,
): (value: Reference | Reference[]) => Observable<string> {
  const display = repository.displayProvider();
  const one = (ref: Reference): Observable<string> =>
    ref?.$ref
      ? repository.retrieve(ref.$ref).pipe(
          take(1),
          map((item) => (item ? display.display(item) : undefined) || ref.$ref),
        )
      : of('');
  return (value) => {
    if (!Array.isArray(value)) {
      return one(value);
    }
    return value.length ? combineLatest(value.map(one)).pipe(map((labels) => labels.join(', '))) : of('');
  };
}

/** Los campos sensibles no muestran su valor. */
export function maskedDisplay(): string {
  return '••••••';
}
